import React, { useState } from "react";
import { addStudy, addNotice, uploadImage } from "../services/api";

const AdminDashboard = () => {

const [subject, setSubject] = useState("");
const [content, setContent] = useState("");

const [title, setTitle] = useState("");
const [noticeContent, setNoticeContent] = useState("");

const [image, setImage] = useState(null);

// ---------------- STUDY ----------------
const handleStudy = async () => {
await addStudy({ subject, content });
alert("✅ Study Added");
};

// ---------------- NOTICE ----------------
const handleNotice = async () => {
await addNotice({ title, content: noticeContent });
alert("✅ Notice Added");
};

// ---------------- IMAGE ----------------
const handleImage = async () => {
const formData = new FormData();
formData.append("image", image);

```
await uploadImage(formData);
alert("✅ Image Uploaded");
```

};

return (
<div style={{ padding: "20px" }}> <h2>👨‍🏫 Admin Dashboard</h2>

  {/* Study */}
  <h3>Add Study Material</h3>
  <input placeholder="Subject" onChange={(e) => setSubject(e.target.value)} />
  <br />
  <textarea placeholder="Content" onChange={(e) => setContent(e.target.value)} />
  <br />
  <button onClick={handleStudy}>Add Study</button>

  {/* Notice */}
  <h3>Add Notice</h3>
  <input placeholder="Title" onChange={(e) => setTitle(e.target.value)} />
  <br />
  <textarea placeholder="Content" onChange={(e) => setNoticeContent(e.target.value)} />
  <br />
  <button onClick={handleNotice}>Add Notice</button>

  {/* Image */}
  <h3>Upload Image</h3>
  <input type="file" onChange={(e) => setImage(e.target.files[0])} />
  <br />
  <button onClick={handleImage}>Upload Image</button>
</div>


);
};

export default AdminDashboard;
